import midseason2025 as MS25, midseason2024 as MS24

PAL = T.palette()

# the wordmark, inlined so the card renders without a network fetch
_UNUSED = ""
_LOGO_SVG = Path("../assets/img/logo.svg").read_text(encoding="utf-8")


def mast(fg=None, ground=None):
    """The wordmark, identical on every card.

    It used to be recoloured per club, which a flat gold mark needed. The
    leather mark carries its own colours and stays as drawn. The arguments
    are kept so the call sites do not all have to change.
    """
    uri = "data:image/svg+xml;base64," + base64.b64encode(
        _LOGO_SVG.encode("utf-8")).decode()
    return f'<img class="mast-logo" src="{uri}" alt="3rd &amp; Long">'


MAST = mast()

NAME_TO_SLUG = T.NAME_TO_SLUG

FONTS = ('<link rel="preconnect" href="https://fonts.googleapis.com">'
         '<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>'
         '<link rel="stylesheet" href="https://fonts.googleapis.com/css2?'
         'family=Archivo+Narrow:wght@500;600;700&'
         'family=Zilla+Slab:wght@400;600;700&display=swap">')

BASE = """
*{box-sizing:border-box;margin:0;padding:0}
body{width:1200px;height:630px;overflow:hidden;background:#101418;color:#EDEEE9;
 font-family:"Zilla Slab",Georgia,serif}
.mast{font-family:"Archivo Narrow",sans-serif;font-weight:700;font-size:24px;
 text-transform:uppercase;letter-spacing:.28em}
/* the 3 drives the artwork height, so the small type needs a taller box than
   a text mast to stay readable at card scale */
.mast-logo{display:block;height:62px;width:auto}
.kick{font-family:"Archivo Narrow",sans-serif;font-weight:600;font-size:21px;
 text-transform:uppercase;letter-spacing:.2em;color:#8B9490}
.who{font-family:"Archivo Narrow",sans-serif;font-weight:600;font-size:21px;
 text-transform:uppercase;letter-spacing:.16em}
"""

def page(css, body):
    return (f'<!doctype html><html><head><meta charset="utf-8">{FONTS}'
            f"<style>{BASE}{css}</style></head><body>{body}</body></html>")


